import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 조회 가능한 조직원은 재직 중인 조직원이다 (퇴직자는 권한 범위 밖).
const VIEWABLE_STATUS = '재직';
// 가정: 업무활동 구분은 전자결재, 게시판 두 가지다.
const ACTIVITY_TYPES = ['전자결재', '게시판'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function paging(query: Record<string, unknown>): { page: number; size: number } {
  const rawPage = query['page'];
  const rawSize = query['size'];
  const page = rawPage === undefined || rawPage === '' ? 0 : Number(rawPage);
  const size = rawSize === undefined || rawSize === '' ? DEFAULT_SIZE : Number(rawSize);
  if (!Number.isInteger(page) || page < 0) {
    throw invalid('page는 0 이상의 정수여야 합니다.');
  }
  if (!Number.isInteger(size) || size < 1) {
    throw invalid('size는 1 이상의 정수여야 합니다.');
  }
  return { page, size: Math.min(size, MAX_SIZE) };
}

function idOf(value: unknown): string {
  if (typeof value !== 'string' || !/^[0-9]{1,18}$/.test(value)) {
    throw invalid('조직원 ID 형식이 올바르지 않습니다.');
  }
  return value;
}

@Controller('api/v1')
export class FnSfr03902Controller {
  @Get('/employees')
  async listEmployees(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query) as Record<string, unknown>;
    const keyword = typeof query['keyword'] === 'string' ? query['keyword'].trim() : '';
    if (keyword === '') {
      throw invalid('검색어를 입력해 주세요.');
    }
    const { page, size } = paging(query);
    return transaction(async (db) => {
      const params = {
        keyword,
        status: VIEWABLE_STATUS,
        limit: size,
        offset: page * size,
      };
      const where = `e.employment_status = :status
        AND (e.name ILIKE '%' || :keyword || '%' OR d.name ILIKE '%' || :keyword || '%')`;
      const items = await db.query(
        `SELECT e.employee_id AS "employeeId", e.name AS "name", d.name AS "departmentName"
         FROM employee e
         LEFT JOIN department d ON d.department_id = e.department_id
         WHERE ${where}
         ORDER BY e.name, e.employee_id
         LIMIT :limit OFFSET :offset`,
        params,
      );
      const counted = await db.query(
        `SELECT COUNT(*) AS "total"
         FROM employee e
         LEFT JOIN department d ON d.department_id = e.department_id
         WHERE ${where}`,
        { keyword, status: VIEWABLE_STATUS },
      );
      const total = Number(counted[0]['total']);
      return { items, page, size, total };
    });
  }

  @Get('/employees/:employeeId')
  async getEmployee(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const employeeId = idOf(req.params['employeeId']);
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT e.employee_no AS "employeeNo", e.name AS "name", e.email AS "email",
                e.mobile_phone AS "mobilePhone", d.name AS "departmentName",
                h.position_name AS "positionName", e.employment_status AS "employmentStatus"
         FROM employee e
         LEFT JOIN department d ON d.department_id = e.department_id
         LEFT JOIN hr_record h ON h.employee_id = e.employee_id
         WHERE e.employee_id = CAST(:employeeId AS bigint)`,
        { employeeId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '조직원을 찾을 수 없습니다.');
      }
      const row = rows[0];
      if (row['employmentStatus'] !== VIEWABLE_STATUS) {
        throw new ApiError(422, 'EMPLOYEE_VIEW_FORBIDDEN', '조회 권한 범위 밖 조직원입니다.');
      }
      // 가정: 이메일·휴대전화번호 열람은 개인정보 열람으로 접속·사용 로그에 기록한다.
      await db.execute(
        `INSERT INTO access_log (employee_id, event_type, accessed_at, login_ip, login_type, target_info_type, created_at, updated_at)
         VALUES (CAST(:userId AS bigint), '개인정보열람', now(), :ip, '웹', '조직원 연락처', now(), now())`,
        { userId: user.id, ip: String(req.ip ?? '').slice(0, 45) },
      );
      return {
        employeeNo: row['employeeNo'],
        name: row['name'],
        email: row['email'],
        mobilePhone: row['mobilePhone'],
        departmentName: row['departmentName'],
        positionName: row['positionName'],
      };
    });
  }

  @Get('/employees/:employeeId/activities')
  async listEmployeeActivities(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const employeeId = idOf(req.params['employeeId']);
    const query = checks.queryOf(req.query) as Record<string, unknown>;
    const rawType = query['activityType'];
    const activityType = typeof rawType === 'string' && rawType.trim() !== '' ? rawType.trim() : null;
    if (activityType !== null && !ACTIVITY_TYPES.includes(activityType)) {
      throw invalid('업무활동 구분이 올바르지 않습니다.');
    }
    const { page, size } = paging(query);
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT employment_status AS "employmentStatus"
         FROM employee WHERE employee_id = CAST(:employeeId AS bigint)`,
        { employeeId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '조직원을 찾을 수 없습니다.');
      }
      if (found[0]['employmentStatus'] !== VIEWABLE_STATUS) {
        throw new ApiError(422, 'ACTIVITY_VIEW_FORBIDDEN', '열람 권한 범위 밖 활동 내역입니다.');
      }
      // 열람 권한 범위: 보안문서·임시저장은 본인만, 게시물은 공개범위(전체/부서/개인)에 따른다.
      const source = `
        SELECT '전자결재' AS "activityType", a.title AS "title",
               COALESCE(a.submitted_at, a.created_at) AS "activityAt"
        FROM approval_document a
        WHERE a.drafter_id = CAST(:employeeId AS bigint)
          AND ((a.is_secret = false AND a.approval_status <> '기안')
               OR a.drafter_id = CAST(:userId AS bigint))
        UNION ALL
        SELECT '게시판' AS "activityType", p.title AS "title", p.created_at AS "activityAt"
        FROM post p
        WHERE p.author_id = CAST(:employeeId AS bigint)
          AND (p.visibility_scope = 'ALL'
               OR p.author_id = CAST(:userId AS bigint)
               OR (p.visibility_scope = 'DEPARTMENT' AND EXISTS (
                     SELECT 1 FROM employee viewer
                     JOIN employee author ON author.employee_id = p.author_id
                     WHERE viewer.employee_id = CAST(:userId AS bigint)
                       AND viewer.department_id = author.department_id)))`;
      const filter = `(CAST(:activityType AS text) IS NULL OR t."activityType" = CAST(:activityType AS text))`;
      const base = { employeeId, userId: user.id, activityType };
      const items = await db.query(
        `SELECT t."activityType", t."title", t."activityAt"
         FROM (${source}) t
         WHERE ${filter}
         ORDER BY t."activityAt" DESC
         LIMIT :limit OFFSET :offset`,
        { ...base, limit: size, offset: page * size },
      );
      const counted = await db.query(
        `SELECT COUNT(*) AS "total" FROM (${source}) t WHERE ${filter}`,
        base,
      );
      const total = Number(counted[0]['total']);
      return { items, page, size, total };
    });
  }
}

