import { useState } from 'react';
import {
  call,
  useData,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Field,
  TextInput,
  Select,
  DateText,
  ErrorText,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const SIZE = 20;
const EMPTY: Page = { items: [], page: 0, size: SIZE, total: 0 };
const TYPE_OPTIONS: [string, string][] = [
  ['전자결재', '전자결재'],
  ['게시판', '게시판'],
];

function EmployeeDetail({ role, employeeId, onClose }: { role: string; employeeId: number; onClose: () => void }) {
  const [activityType, setActivityType] = useState('');
  const [page, setPage] = useState(0);
  const profile = useData<Row>(
    () => call<Row>('GET', `/employees/${employeeId}`, role),
    [employeeId, role],
  );
  const activities = useData<Page>(
    () => call<Page>('GET', `/employees/${employeeId}/activities`, role, undefined, { activityType, page, size: SIZE }),
    [employeeId, role, activityType, page],
  );
  const p = profile.data;
  return (
    <Drawer title="조직원 프로필" onClose={onClose}>
      {profile.error ? <ErrorText text={profile.error} /> : null}
      {p ? (
        <Pairs
          items={[
            ['사번', String(p.employeeNo ?? '')],
            ['성명', String(p.name ?? '')],
            ['부서명', String(p.departmentName ?? '')],
            ['직위', String(p.positionName ?? '')],
            ['이메일', String(p.email ?? '')],
            ['휴대전화번호', String(p.mobilePhone ?? '')],
          ]}
        />
      ) : null}
      <h2>활동 내역</h2>
      <Field label="업무활동 구분">
        <Select
          value={activityType}
          onChange={(v) => {
            setActivityType(v);
            setPage(0);
          }}
          options={TYPE_OPTIONS}
          placeholder="전체"
        />
      </Field>
      {activities.error ? <ErrorText text={activities.error} /> : null}
      <DataTable
        columns={[
          { key: 'activityType', label: '업무활동 구분' },
          { key: 'title', label: '활동 제목' },
          { key: 'activityAt', label: '활동 일시', render: (r) => <DateText value={r.activityAt} time /> },
        ]}
        rows={activities.data?.items ?? []}
        empty="활동 내역이 없습니다."
      />
      <Pager page={page} size={SIZE} total={activities.data?.total ?? 0} onPage={setPage} />
    </Drawer>
  );
}

export default function FnSfr03902Page({ role }: PageProps) {
  const [input, setInput] = useState('');
  const [keyword, setKeyword] = useState('');
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<number | null>(null);
  const [message, setMessage] = useState('');

  const list = useData<Page>(async () => {
    if (keyword === '') {
      return EMPTY;
    }
    return call<Page>('GET', '/employees', role, undefined, { keyword, page, size: SIZE });
  }, [keyword, page, role]);

  const search = () => {
    const word = input.trim();
    if (word === '') {
      setMessage('검색어를 입력해 주세요.');
      return;
    }
    setMessage('');
    setPage(0);
    setKeyword(word);
  };

  const reset = () => {
    setInput('');
    setKeyword('');
    setPage(0);
    setMessage('');
  };

  const total = list.data?.total ?? 0;

  return (
    <div className="bento">
      <section className="box span-8">
        <h2>조직원 검색</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="이름 또는 부서 검색어" required>
            <TextInput value={input} onChange={setInput} placeholder="이름 또는 부서명" />
          </Field>
        </Filters>
        {message ? <ErrorText text={message} /> : null}
        {list.error ? <ErrorText text={list.error} /> : null}
        <Band total={total} />
        <DataTable
          columns={[
            { key: 'name', label: '성명' },
            { key: 'departmentName', label: '부서명' },
          ]}
          rows={list.data?.items ?? []}
          onRowClick={(row) => setSelected(Number(row.employeeId))}
          empty={keyword === '' ? '검색어를 입력해 조회하세요.' : '검색 결과가 없습니다.'}
        />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>
      <section className="box span-4">
        <h2>검색 결과</h2>
        <Tiles items={[['조직원 수', total]]} />
      </section>
      {selected !== null ? (
        <EmployeeDetail role={role} employeeId={selected} onClose={() => setSelected(null)} />
      ) : null}
    </div>
  );
}
